  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Salicylic acid, which shares the 2-hydroxyphenyl and carboxylic acid motifs, showed essentially complete systemic availability after oral administration in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Probenecid, an aromatic carboxylic acid drug, showed ~100% oral bioavailability in humans, supporting high F for the query's carboxylate-containing structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Eltrombopag, a larger polyaromatic oral carboxylic acid drug with a phenol, had at least 52% oral bioavailability in healthy volunteers, supporting high F for the query despite its size.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Brequinar, a polyaromatic carboxylic acid, showed >90% oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Y-20811, a carboxylic acid drug, had absolute oral bioavailability of 0.72-0.81, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "6-MNA, an aromatic carboxylic acid metabolite, had ~35% absolute oral bioavailability, still above the 20% threshold, supporting high F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferable evidence from structurally related oral carboxylic acid drugs indicates high oral bioavailability (F >=20%); the query's carboxylic acid and phenolic groups are consistent with good absorption, and no affirmative evidence supports low F.",
  "evidence_gaps": [
    "No direct absolute bioavailability record for the query molecule; evidence is from analogues with modest Morgan similarity (0.22-0.32).",
    "The query is larger and less soluble than most analogues, so solubility-limited absorption could reduce F, though the consistent high-F analogues make F <20% unlikely."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

